package com.rescuefarm.ui.checkout;
import androidx.lifecycle.*;import com.rescuefarm.data.repository.OrderRepository;import com.rescuefarm.domain.model.Order;
public class OrderViewModel extends ViewModel{private final OrderRepository repo;private final MutableLiveData<CheckoutState> state=new MutableLiveData<>(CheckoutState.idle());public OrderViewModel(OrderRepository r){repo=r;}public LiveData<CheckoutState> getState(){return state;}public void findGuest(String code,String phone){state.setValue(CheckoutState.loading());repo.findGuestOrder(code,phone,new OrderRepository.OrderCallback(){public void onSuccess(Order o,boolean replay){state.postValue(CheckoutState.success(o,replay));}public void onError(OrderRepository.ErrorCode e,String m){state.postValue(CheckoutState.error(m));}});}@Override protected void onCleared(){repo.close();super.onCleared();}}
